do $patch$ declare definition text; begin select pg_get_functiondef('public.odap_rpc(text,text,text,text,jsonb)'::regprocedure) into definition; if position($old$then to_jsonb(p)-'body' else to_jsonb(p) end$old$ in definition)>0 then definition:=replace(definition,$old$then to_jsonb(p)-'body' else to_jsonb(p) end$old$,$new$then jsonb_build_object('id',p.id,'student_id',p.student_id,'title',p.title,'status',p.status,'created_at',p.created_at,'files',p.files,'verified',p.verified) else to_jsonb(p) end$new$); execute definition; elsif position($new$then jsonb_build_object('id',p.id,'student_id',p.student_id,'title',p.title,'status',p.status,'created_at',p.created_at,'files',p.files,'verified',p.verified) else to_jsonb(p) end$new$ in definition)=0 then raise exception 'Unexpected packet metadata function; patch not applied'; end if;end $patch$;